{
  "name": "semana-academica-api",
  "version": "1.0.0",
  "private": true,
  "type": "module",
  "description": "API da Semana Acadêmica 2026 — Express + SQLite",
  "main": "src/server.js",
  "scripts": {
    "start": "node src/server.js",
    "test": "node --test verificacoes/"
  },
  "dependencies": {
    "better-sqlite3": "^11.10.0",
    "express": "^4.21.2"
  }
}

import Database from 'better-sqlite3';
import { USUARIOS, SALAS } from './dados-iniciais.js';

export function novoBanco(caminho) {
  const banco = new Database(caminho);
  banco.pragma('foreign_keys = ON');
  banco.exec(`
    CREATE TABLE IF NOT EXISTS usuarios (
      id TEXT PRIMARY KEY,
      nome TEXT NOT NULL,
      papel TEXT NOT NULL
    );
    CREATE TABLE IF NOT EXISTS salas (
      id TEXT PRIMARY KEY,
      nome TEXT NOT NULL,
      capacidade INTEGER NOT NULL
    );
    CREATE TABLE IF NOT EXISTS atividades (
      id TEXT PRIMARY KEY,
      titulo TEXT NOT NULL,
      tipo TEXT NOT NULL,
      salaId TEXT NOT NULL,
      vagas INTEGER NOT NULL,
      cancelada INTEGER NOT NULL DEFAULT 0,
      FOREIGN KEY (salaId) REFERENCES salas(id)
    );
    CREATE TABLE IF NOT EXISTS encontros (
      id TEXT PRIMARY KEY,
      atividadeId TEXT NOT NULL,
      inicio TEXT NOT NULL,
      fim TEXT NOT NULL,
      FOREIGN KEY (atividadeId) REFERENCES atividades(id)
    );
  `);
  return banco;
}

export function carregarDadosIniciais(banco) {
  const usuario = banco.prepare('INSERT INTO usuarios (id, nome, papel) VALUES (?, ?, ?)');
  const sala = banco.prepare('INSERT INTO salas (id, nome, capacidade) VALUES (?, ?, ?)');
  for (const u of USUARIOS) usuario.run(u.id, u.nome, u.papel);
  for (const s of SALAS) sala.run(s.id, s.nome, s.capacidade);
}

export function resetarBanco(banco) {
  banco.exec('DELETE FROM encontros; DELETE FROM atividades; DELETE FROM salas; DELETE FROM usuarios;');
  carregarDadosIniciais(banco);
}

import { INICIO_DO_RELOGIO } from './dados-iniciais.js';

let fixo = null;

export function ehModoTeste() {
  return process.env.MODO_TESTE === '1';
}

export function agora() {
  if (!ehModoTeste()) return new Date();
  if (fixo === null) fixo = new Date(INICIO_DO_RELOGIO);
  return fixo;
}

export function resetarRelogio() {
  if (!ehModoTeste()) return false;
  fixo = new Date(INICIO_DO_RELOGIO);
  return true;
}

export function definirRelogio(iso) {
  if (!ehModoTeste()) return false;
  const instante = new Date(iso);
  if (Number.isNaN(instante.getTime())) return false;
  fixo = instante;
  return true;
}

