import express from 'express';
import { novoBanco, resetarBanco } from './banco.js';
import { ehModoTeste, agora, resetarRelogio, definirRelogio } from './relogio.js';
import { INICIO_DO_RELOGIO } from './dados-iniciais.js';

export function criarServidor({ banco = novoBanco(':memoria:') } = {}) {
  resetarBanco(banco);
  const app = express();
  app.use(express.json());

  function usuarioPorId(id) {
    return banco.prepare('SELECT id, nome, papel FROM usuarios WHERE id = ?').get(id);
  }

  function exigirUsuario(req, res, next) {
    const id = req.get('X-Usuario');
    const usuario = id ? usuarioPorId(id) : undefined;
    if (!usuario) {
      return res.status(401).json({ erro: 'USUARIO_DESCONHECIDO', mensagem: 'Usuário não reconhecido.' });
    }
    req.usuario = usuario;
    next();
  }

  if (ehModoTeste()) {
    app.post('/_teste/reset', (req, res) => {
      resetarBanco(banco);
      resetarRelogio();
      res.status(204).end();
    });

    app.get('/_teste/relogio', (req, res) => {
      res.json({ agora: agora().toISOString() });
    });

    app.put('/_teste/relogio', (req, res) => {
      const iso = req.body && req.body.agora;
      if (typeof iso !== 'string' || !definirRelogio(iso)) {
        return res.status(422).json({ erro: 'DADOS_INVALIDOS', mensagem: 'Envie {"agora": "<ISO>"}.' });
      }
      res.json({ agora: agora().toISOString() });
    });
  }

  return app;
}
