Compute:
```js
function serializarAtividade(linha) {
  const encontros = banco
    .prepare('SELECT id, inicio, fim FROM encontros WHERE atividadeId = ? ORDER BY inicio')
    .all(linha.id);
  const cargaHorariaMinutos = Math.round(
    encontros.reduce((soma, e) => soma + (Date.parse(e.fim) - Date.parse(e.inicio)) / 60000, 0),
  );
  let situacao = 'prevista';
  const primeiro = encontros[0];
  const ultimo = encontros[encontros.length - 1];
  const agoraMs = agora().getTime();
  if (linha.cancelada) {
    situacao = 'cancelada';
  } else if (agoraMs >= Date.parse(ultimo.fim)) {
    situacao = 'encerrada';
  } else if (agoraMs >= Date.parse(primeiro.inicio)) {
    situacao = 'em_andamento';
  }
  return {
    id: linha.id,
    titulo: linha.titulo,
    tipo: linha.tipo,
    salaId: linha.salaId,
    vagas: linha.vagas,
    encontros: encontros.map((e) => ({ id: e.id, inicio: e.inicio, fim: e.fim })),
    cargaHorariaMinutos,
    situacao,
    ocupadas: 0,
    vagasRestantes: linha.vagas,
    emEspera: 0,
  };
}
```

Need `agora` import already in app.js. Good.

